mapper.insert:
INSERT INTO provider_native_connect_session (
  user_id, provider, status, pairing_code_hash, expires_at
) VALUES (
  #{userId}, #{provider}, #{status}, #{pairingCodeHash}, #{expiresAt}
)

mapper.update:
UPDATE provider_native_connect_session
SET status = 'failed', error_code = #{errorCode}
WHERE user_id = #{userId}
  AND provider = #{provider}
  AND status IN ('pending', 'prepared', 'exchanging')

UPDATE provider_native_connect_session
SET status = 'exchanging', error_code = NULL
WHERE id = #{id}
  AND handoff_ticket_hash = #{handoffTicketHash}
  AND status = 'prepared'
  AND expires_at > UTC_TIMESTAMP(6)

UPDATE provider_native_connect_session
SET status = 'failed', error_code = #{errorCode}
WHERE id = #{id} AND status = #{expectedStatus}
